# Generated by tools/render_controls.py — edit the data files, not this file.
#
# Rule:        CKV_AWS_61 (checkov 3.3.16)
# Applies to:  aws_iam_role
# Read with:   aws_policy_documents — aws_iam_role → no_account_root_principal
#              predicate: libraries/_policy_document.rb
#              fetch:     tools/policy_specs.yml
#
# The rule id is the identity: file name, control id and `tag checkov_id` all
# carry it, and tools/lint_catalog_drift.py asserts the three agree.

scan_regions = input('scan_regions')
exempt       = (input('exempt_assets') || {})['CKV_AWS_61'] || []

control 'CKV_AWS_61' do
  title 'Ensure AWS IAM policy does not allow assume role permission across all services'

  desc <<~DESC
    Checkov asserts this against the policy document in the Terraform. This
    profile fetches the policy AWS actually has on each aws_iam_role and
    evaluates the same question over its statements: no statement grants an
    account root principal.

    Stronger than Checkov: an account-root trust is the classic thing added
    by hand to "just make it work" during an incident and never narrowed
    afterwards, so it is disproportionately likely to exist only in the
    deployed document.
  DESC

  desc 'rationale', <<~RATIONALE
    Trusting an account root delegates the decision about who may assume the
    role to that account's own IAM, which means the permissions the role
    carries are available to every identity in that account, present and
    future, including ones created long after anyone reviewed this trust.
    The role's blast radius stops being a property of this account's
    configuration and becomes a property of somebody else's.
  RATIONALE

  desc 'check', <<~CHECK
    Checkov looks for: aws_iam_role: the assume_role_policy has no statement
    whose Principal.AWS is a bare 12-digit account id or an
    arn:aws:iam::<account>:root ARN — the role is assumable by named
    principals, not by an entire account
  CHECK

  desc 'fix', <<~'FIX'
    Terraform — aws_iam_role:

      resource "aws_iam_role" "app" {
        name = "app"

        assume_role_policy = jsonencode({
          Version = "2012-10-17"
          Statement = [
            {
              Effect    = "Allow"
              Principal = { AWS = "arn:aws:iam::${var.partner_account_id}:role/partner-integration" }
              Action    = "sts:AssumeRole"
              Condition = {
                StringEquals = { "sts:ExternalId" = var.external_id }
              }
            },
          ]
        })
      }

    Out of band — aws_iam_role:

      aws iam update-assume-role-policy --role-name <role-name> --policy-document file://trust-policy.json

    Note (aws_iam_role): Name the role or user that actually assumes this role
    rather than the account it lives in. Where the far side genuinely cannot
    commit to a single principal ARN, keep the account-level trust but add
    sts:ExternalId (or aws:PrincipalOrgID for an organization member) — that is
    the documented AWS pattern for third-party access and it is what turns
    "anyone in that account" into "the integration we agreed to". This control
    reports an own-account root trust too, because the deployed document cannot
    say which account was intended; an own-account root trust is still the whole
    account and is still worth narrowing.
  FIX

  tag checkov_id:            'CKV_AWS_61'
  tag checkov_category:      'IAM'
  tag checkov_version:       '3.3.16'
  tag checkov_kind:          'custom'
  tag tf_resources:          %w[aws_iam_role]
  tag tf_docs:               'https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/iam_role'
  tag policy_source:         'aws_iam_role'
  tag policy_predicate:      'no_account_root_principal'
  tag nist:                  ['AC-3', 'AC-6']
  tag nist_r4:               ['AC-3', 'AC-6']
  tag cci:                   ['CCI-000213', 'CCI-000225']
  tag ksi:                   ['KSI-IAM-CTL']
  tag severity:              'medium'
  tag severity_source:       'assessed'
  tag nist_source:           'agent-drafted'
  tag implementation_status: 'implemented'

  assets = aws_policy_documents(type: 'aws_iam_role', source: 'aws_iam_role',
                                predicate: 'no_account_root_principal', regions: scan_regions)

  # A region — or a whole service — that could not be READ is not the same as
  # one with nothing in it. A denied call or an unreachable endpoint ends up
  # here, and without this assertion it renders as "no assets" and the control
  # reports Not Applicable: the worst case reported as "does not apply here".
  unreadable = assets.unreadable_regions
  unless unreadable.empty?
    describe 'aws_iam_role enumeration' do
      it 'read every region it attempted' do
        expect(unreadable.map { |r| "#{r[:region]}: #{r[:error]}" }).to be_empty
      end
    end
  end

  # An asset whose policy could not be read or parsed has NO VERDICT. It is not
  # in `assets` below, because a nil offender list compared against [] would
  # pass — a denied GetPolicy silently reporting the least-visible estate as the
  # cleanest one. It fails here instead, naming the asset and the reason.
  #
  # An asset with no policy at all is NOT here: that is a real answer and a
  # passing one, recorded on the row as policy_present: false.
  undecidable = assets.undecidable
  unless undecidable.empty?
    describe 'aws_iam_role policy documents' do
      it 'could all be read and parsed' do
        expect(undecidable).to be_empty
      end
    end
  end

  in_scope = assets.assets(exempt: exempt)

  # Both failure lists keep the control APPLICABLE. only_if suppresses the whole
  # control, including the two assertions above, so a guard that skips when the
  # enumeration broke is no guard at all: it would suppress exactly the case it
  # exists to catch.
  applicable = !in_scope.empty? || !undecidable.empty? || !unreadable.empty?

  # Two statements, not a ternary: InSpec's AST impact collector calls `.value`
  # on the argument node, and a ternary is an IfNode with none — it aborts
  # `check` for the whole profile before a single control runs.
  impact 0.5
  impact 0.0 unless applicable

  only_if('no aws_iam_role in scope') { applicable }

  in_scope.each do |asset|
    describe "aws_iam_role #{asset[:id]} (#{asset[:account_id]}/#{asset[:region]})" do
      it 'no statement grants an account root principal' do
        expect(asset[:offenders]).to eq([]),
          "#{asset[:offenders].length} offending statement(s) — " \
          "#{asset[:offenders].join(' | ')}"
      end
    end
  end
end
